dashboard.definition:
{
 "title": "Cisco Spaces \u2014 Intelligence",
 "description": "[2026-04-25 18:10] Advanced Cisco Spaces analytics \u2014 environmental trends, ML predictions, room utilization, activation readiness, and visitor intelligence.",
 "inputs": {
 "input_global_trp": {
 "options": {
 "defaultValue": "-14d@d,now",
 "token": "global_time"
 },
 "title": "Time range",
 "type": "input.timerange"
 }
 },
 "defaults": {
 "dataSources": {}
 },
 "visualizations": {
 "viz_act_box": {
 "options": {
 "fillColor": "#FFFFFF",
 "strokeColor": "#E0E0E0"
 },
 "type": "splunk.rectangle"
 },
 "viz_act_compare_chart": {
 "dataSources": {
 "primary": "ds_act_compare_chart"
 },
 "description": "People / unique users / unique devices: baseline week vs exercise week.",
 "options": {
 "backgroundColor": "transparent",
 "legendDisplay": "bottom",
 "seriesColors": [
 "#9E9E9E",
 "#D64550"
 ],
 "xAxisTitleVisibility": "hide",
 "yAxisTitleText": "Avg per hour"
 },
 "title": "Spaces baseline \u00d7 exercise \u2014 same metrics, side-by-side",
 "type": "splunk.column"
 },
 "viz_act_compare_kpi": {
 "dataSources": {
 "primary": "ds_act_compare_kpi"
 },
 "description": "Surge multiplier \u2014 Op Florida Ready vs the prior baseline week.",
 "options": {
 "backgroundColor": "transparent",
 "majorColor": "> primary | seriesByName('multiplier') | lastPoint() | rangeValue(thresholds=[1.5, 3], colors=[\"#9E9E9E\", \"#FF8C25\", \"#D64550\"])",
 "unit": "x",
 "unitPosition": "after"
 },
 "title": "Spaces baseline \u00d7 exercise \u2014 surge multiplier",
 "type": "splunk.singlevalue"
 },
 "viz_act_env": {
 "dataSources": {
 "primary": "ds_activation_env"
 },
 "description": "Avg temp & humidity over the activation period.",
 "options": {
 "nullValueDisplay": "connect",
 "seriesColors": [
 "#D64550",
 "#049FD9"
 ]
 },
 "title": "Webex \u2014 temperature & humidity during activation",
 "type": "splunk.line"
 },
 "viz_act_hdr": {
 "options": {
 "fontColor": "#D64550",
 "markdown": "**Activation Readiness**"
 },
 "type": "splunk.markdown"
 },
 "viz_act_info": {
 "options": {
 "fontColor": "#2B2B2B",
 "markdown": "**Known exercises:** \nOperation Florida Ready \u2014 **April 13\u201315, 2026** (SEOC, Tallahassee) | TLH Airport Full-Scale Exercise \u2014 **Feb 19, 2026** | Symposium \u2014 annual training event \n\n**Heads-up on this year's data:** Cisco Spaces data started landing in Splunk ~April 16, 2026 \u2014 *after* this year's exercise. So time-series tiles starting before Apr 16 will look empty until the picker covers the live window. Pick **Last 30 days** (or the bundled \"Op Florida Ready 2026\" presets) to see the date markers; they will line up against real occupancy in 2027. \n\nSEOC activation levels: **Level 3** (monitoring) \u2192 **Level 2** (partial) \u2192 **Level 1** (full scale). Look for occupancy surges at SEOC, elevated WiFi pressure on SSIDs, and temperature spikes from increased personnel."
 },
 "type": "splunk.markdown"
 },
 "viz_act_kpi_capacity": {
 "dataSources": {
 "primary": "ds_activation_kpi_capacity"
 },
 "description": "Peak building capacity-percent during the activation.",
 "options": {
 "majorColor": "#FF8C25"
 },
 "title": "Peak capacity %",
 "type": "splunk.singlevalue"
 },
 "viz_act_kpi_peak": {
 "dataSources": {
 "primary": "ds_activation_kpi_peak"
 },
 "description": "Peak users during a known exercise.",
 "options": {
 "majorColor": "#049FD9"
 },
 "title": "Peak users",
 "type": "splunk.singlevalue"
 },
 "viz_act_kpi_ssid": {
 "dataSources": {
 "primary": "ds_activation_kpi_ssid"
 },
 "description": "Total wireless associations during the activation.",
 "options": {
 "majorColor": "#6EBE4A"
 },
 "title": "WiFi associations",
 "type": "splunk.singlevalue"
 },
 "viz_act_kpi_temp": {
 "dataSources": {
 "primary": "ds_activation_kpi_temp"
 },
 "description": "Peak temperature during the activation.",
 "options": {
 "majorColor": "#D64550",
 "unit": "\u00b0F"
 },
 "title": "Peak temperature",
 "type": "splunk.singlevalue"
 },
 "viz_act_surge": {
 "dataSources": {
 "annotation": "ds_activation_annotation",
 "primary": "ds_activation_surge"
 },
 "description": "Hour-by-hour total occupancy during the selected window. Red markers show exact dates/times of known exercises (e.g., Operation Florida Ready). Lets you see surges line up with declared activations.",
 "options": {
 "annotationColor": [
 "#D64550"
 ],
 "annotationLabel": [
 "label"
 ],
 "nullValueDisplay": "connect",
 "seriesColors": [
 "#049FD9"
 ]
 },
 "title": "Spaces \u2014 occupancy surge + Op Florida Ready annotations",
 "type": "splunk.area"
 },
 "viz_act_wifi": {
 "dataSources": {
 "annotation": "ds_activation_annotation",
 "primary": "ds_activation_wifi"
 },
 "description": "Hourly WiFi associations stacked by SSID + exercise overlays.",
 "options": {
 "annotationColor": [
 "#D64550"
 ],
 "annotationLabel": [
 "label"
 ],
 "seriesColors": [
 "#049FD9",
 "#6EBE4A",
 "#7B56DB",
 "#FF8C25"
 ],
 "stackMode": "stacked"
 },
 "title": "Spaces \u2014 WiFi associations by SSID + exercise annotations",
 "type": "splunk.column"
 },
 "viz_ap_health_dist": {
 "dataSources": {
 "primary": "ds_ap_health_dist"
 },
 "description": "Access points grouped by health tier (Excellent \u2192 Poor).",
 "options": {
 "backgroundColor": "transparent",
 "seriesColors": [
 "#00cdaf",
 "#009ceb",
 "#dd9900",
 "#ff677b",
 "#a0a0a0"
 ],
 "showDonutHole": true
 },
 "showLastUpdated": false,
 "showProgressBar": false,
 "title": "DNAC \u2014 access-point health distribution",
 "type": "splunk.pie"
 },
 "viz_ap_health_table": {
 "dataSources": {
 "primary": "ds_ap_health_table"
 },
 "description": "Detailed table for every access point: site, health score, CPU and memory utilization, open issues, client counts on each band, and air-quality / interference scores. The operational worksheet for the wireless team.",
 "options": {
 "backgroundColor": "transparent",
 "fontSize": "small"
 },
 "showLastUpdated": false,
 "showProgressBar": false,
 "title": "DNAC \u2014 access-point detail",
 "type": "splunk.table"
 },
 "viz_band_distribution": {
 "dataSources": {
 "primary": "ds_band_distribution"
 },
 "description": "Wireless clients split by band (2.4 vs 5 GHz).",
 "options": {
 "backgroundColor": "transparent",
 "seriesColors": [
 "#009ceb",
 "#7b56db",
 "#00cdaf"
 ],
 "showDonutHole": true
 },
 "showLastUpdated": false,
 "showProgressBar": false,
 "title": "DNAC \u2014 client radio band split (2.4 vs. 5 GHz)",
 "type": "splunk.pie"
 },
 "viz_cap_box": {
 "options": {
 "fillColor": "#FFFFFF",
 "strokeColor": "#E0E0E0"
 },
 "type": "splunk.rectangle"
 },
 "viz_cap_gauge_first": {
 "dataSources": {
 "primary": "ds_capacity_gauge_first"
 },
 "description": "Peak utilization of the busiest floor.",
 "options": {
 "backgroundColor": "transparent",
 "majorColor": "> primary | seriesByName('Capacity %') | lastPoint() | rangeValue(thresholds=[50, 80], colors=[\"#6EBE4A\", \"#FF8C25\", \"#D64550\"])",
 "unit": "%",
 "unitPosition": "after"
 },
 "title": "Highest capacity floor (period peak)",
 "type": "splunk.singlevalue"
 },
 "viz_cap_gauge_second": {
 "dataSources": {
 "primary": "ds_capacity_gauge_second"
 },
 "description": "Second-busiest floor \u2014 the next pressure point you'd address.",
 "options": {
 "backgroundColor": "transparent",
 "majorColor": "> primary | seriesByName('Capacity %') | lastPoint() | rangeValue(thresholds=[50, 80], colors=[\"#6EBE4A\", \"#FF8C25\", \"#D64550\"])",
 "unit": "%",
 "unitPosition": "after"
 },
 "title": "Second highest capacity floor (period peak)",
 "type": "splunk.singlevalue"
 },
 "viz_cap_hdr": {
 "options": {
 "fontColor": "#D64550",
 "markdown": "**Capacity and Prediction**"
 },
 "type": "splunk.markdown"
 },
 "viz_cap_trend": {
 "dataSources": {
 "annotation": "ds_activation_annotation",
 "primary": "ds_capacity_trend"
 },
 "description": "Estimated capacity percentage from Cisco Spaces",
 "options": {
 "annotationColor": [
 "#D64550"
 ],
 "annotationLabel": [
 "label"
 ],
 "nullValueDisplay": "connect",
 "seriesColors": [
 "#049FD9",
 "#6EBE4A",
 "#7B56DB"
 ]
 },
 "title": "Capacity % by floor over time",
 "type": "splunk.line"
 },
 "viz_capacity_predict": {
 "dataSources": {
 "annotation": "ds_activation_annotation",
 "primary": "ds_capacity_predict"
 },
 "description": "ML predict command projects total users 24 hours forward",
 "options": {
 "annotationColor": [
 "#D64550"
 ],
 "annotationLabel": [
 "label"
 ],
 "nullValueDisplay": "connect",
 "seriesColors": [
 "#049FD9",
 "#D64550",
 "#CCCCCC",
 "#CCCCCC"
 ]
 },
 "title": "Occupancy forecast (24-hour prediction)",
 "type": "splunk.line"
 },
 "viz_client_health_by_site": {
 "dataSources": {
 "annotation": "ds_activation_annotation",
 "primary": "ds_client_health_by_site"
 },
 "description": "Hourly client-health score broken out per site.",
 "options": {
 "annotationColor": [
 "#D64550"
 ],
 "annotationLabel": [
 "label"
 ],
 "backgroundColor": "transparent",
 "legendDisplay": "bottom",
 "seriesColors": [
 "#009ceb",
 "#00cdaf",
 "#7b56db",
 "#dd9900",
 "#ff677b",
 "#cb2196",
 "#813193",
 "#0051b5"
 ],
 "xAxisTitleVisibility": "hide",
 "yAxisTitleText": "Client Health (0-10)"
 },
 "showLastUpdated": false,
 "showProgressBar": false,
 "title": "DNAC \u2014 client health by site over time",
 "type": "splunk.line"
 },
 "viz_convergence_health": {
 "dataSources": {
 "annotation": "ds_convergence_annotations",
 "primary": "ds_convergence_health"
 },
 "description": "DNAC network & client health on the same hourly timeline as issues.",
 "options": {
 "annotationColor": [
 "#D64550"
 ],
 "annotationLabel": [
 "label"
 ],
 "legendDisplay": "bottom",
 "nullValueDisplay": "connect",
 "seriesColors": [
 "#6EBE4A",
 "#7B56DB"
 ],
 "xAxisTitleVisibility": "hide",
 "yAxisTitleText": "Health Score (0-100)"
 },
 "title": "DNAC \u00d7 DNAC \u2014 network & client health + DNAC issues + date annotations",
 "type": "splunk.line"
 },
 "viz_convergence_occupancy": {
 "dataSources": {
 "annotation": "ds_convergence_annotations",
 "primary": "ds_convergence_occupancy"
 },
 "description": "Hourly Spaces occupancy with high-severity DNAC issues marked.",
 "options": {
 "annotationColor": [
 "#D64550"
 ],
 "annotationLabel": [
 "label"
 ],
 "legendDisplay": "off",
 "seriesColors": [
 "#049FD9"
 ],
 "xAxisTitleVisibility": "hide",
 "yAxisTitleText": "Occupancy (people)"
 },
 "title": "Spaces \u00d7 DNAC \u2014 occupancy + DNAC issues + date annotations",
 "type": "splunk.column"
 },
 "viz_dwell_bar": {
 "dataSources": {
 "primary": "ds_dwell_distribution"
 },
 "description": "How long do devices stay connected?",
 "options": {
 "seriesColors": [
 "#049FD9"
 ]
 },
 "title": "Dwell time distribution",
 "type": "splunk.bar"
 },
 "viz_env_box": {
 "options": {
 "fillColor": "#FFFFFF",
 "strokeColor": "#E0E0E0"
 },
 "type": "splunk.rectangle"
 },
 "viz_env_hdr": {
 "options": {
 "fontColor": "#D64550",
 "markdown": "**Environmental Intelligence**"
 },
 "type": "splunk.markdown"
 },
 "viz_env_kpi_humidity": {
 "dataSources": {
 "primary": "ds_env_kpi_humidity"
 },
 "description": "Avg humidity across all Webex sensors.",
 "options": {
 "majorColor": "#049FD9",
 "sparklineDisplay": "below",
 "sparklineStrokeColor": "#049FD9",
 "unit": "%"
 },
 "title": "Avg humidity",
 "type": "splunk.singlevalue"
 },
 "viz_env_kpi_temp": {
 "dataSources": {
 "primary": "ds_env_kpi_temp"
 },
 "description": "Avg temp across all Webex sensors.",
 "options": {
 "majorColor": "#049FD9",
 "sparklineDisplay": "below",
 "sparklineStrokeColor": "#049FD9",
 "unit": "\u00b0F"
 },
 "title": "Avg temperature",
 "type": "splunk.singlevalue"
 },
 "viz_env_overlay": {
 "dataSources": {
 "annotation": "ds_activation_annotation",
 "primary": "ds_env_occupancy_overlay"
 },
 "description": "Do more people mean higher temperatures?",
 "options": {
 "annotationColor": [
 "#D64550"
 ],
 "annotationLabel": [
 "label"
 ],
 "nullValueDisplay": "connect",
 "seriesColors": [
 "#049FD9",
 "#D64550"
 ],
 "xAxisTitleVisibility": "hide"
 },
 "title": "Spaces \u00d7 Webex \u2014 occupancy (columns) + temperature overlay",
 "type": "splunk.area"
 },
 "viz_env_scatter": {
 "dataSources": {
 "primary": "ds_env_scatter"
 },
 "description": "Each dot is one hour \u2014 look for upward trend",
 "options": {
 "seriesColors": [
 "#049FD9"
 ]
 },
 "title": "Spaces \u00d7 Webex \u2014 people vs. temperature correlation",
 "type": "splunk.scatter"
 },
 "viz_env_table": {
 "dataSources": {
 "primary": "ds_env_summary"
 },
 "description": "Latest temperature and humidity per Webex device",
 "options": {
 "fontSize": "small",
 "headerVisibility": "fixed"
 },
 "title": "Current sensor readings",
 "type": "splunk.table"
 },
 "viz_humidity_trend": {
 "dataSources": {
 "annotation": "ds_env_annotation",
 "primary": "ds_humidity_trend"
 },
 "description": "Hourly avg humidity per floor + exercise annotations.",
 "options": {
 "annotationColor": [
 "#D64550"
 ],
 "annotationLabel": [
 "label"
 ],
 "nullValueDisplay": "connect",
 "seriesColors": [
 "#049FD9",
 "#6EBE4A",
 "#7B56DB"
 ],
 "legendDisplay": "bottom",
 "xAxisTitleVisibility": "hide"
 },
 "title": "Webex sensors \u2014 humidity by floor + exercise annotations",
 "type": "splunk.line"
 },
 "viz_issues_by_site": {
 "dataSources": {
 "primary": "ds_issues_by_site"
 },
 "description": "Number of distinct DNAC issues at each site for the time range. Pinpoints the single noisiest location so investigation effort goes where it matters.",
 "options": {
 "backgroundColor": "transparent",
 "dataValuesDisplay": "all",
 "legendDisplay": "off",
 "seriesColors": [
 "#ff677b"
 ],
 "xAxisTitleVisibility": "hide"
 },
 "showLastUpdated": false,
 "showProgressBar": false,
 "title": "DNAC \u2014 issues by site",
 "type": "splunk.column"
 },
 "viz_issues_timeline": {
 "dataSources": {
 "annotation": "ds_activation_annotation",
 "primary": "ds_issues_with_occupancy"
 },
 "description": "DNAC issues stacked by severity (HIGH/MEDIUM/LOW) with occupancy line.",
 "options": {
 "annotationColor": [
 "#D64550"
 ],
 "annotationLabel": [
 "label"
 ],
 "backgroundColor": "transparent",
 "legendDisplay": "bottom",
 "overlayFields": [
 "Occupancy"
 ],
 "seriesColors": [
 "#ff677b",
 "#dd9900",
 "#a0a0a0",
 "#009ceb"
 ],
 "stackMode": "stacked",
 "xAxisTitleVisibility": "hide",
 "yAxisTitleText": "Issues"
 },
 "showLastUpdated": false,
 "showProgressBar": false,
 "title": "DNAC \u00d7 Spaces \u2014 issues by severity (stacked) + occupancy overlay",
 "type": "splunk.column"
 },
 "viz_kpi_avg_week": {
 "dataSources": {
 "primary": "ds_kpi_avg_week"
 },
 "description": "Average people-on-site across the period.",
 "options": {
 "majorColor": "#6EBE4A"
 },
 "title": "Avg users (period)",
 "type": "splunk.singlevalue"
 },
 "viz_kpi_peak_today": {
 "dataSources": {
 "primary": "ds_kpi_peak_today"
 },
 "description": "Busiest hour in the period.",
 "options": {
 "majorColor": "#049FD9"
 },
 "title": "Peak users today",
 "type": "splunk.singlevalue"
 },
 "viz_kpi_repeat": {
 "dataSources": {
 "primary": "ds_kpi_repeat_pct"
 },
 "description": "Share of devices seen more than once.",
 "options": {
 "majorColor": "#6EBE4A",
 "unit": "%"
 },
 "title": "Repeat visitors",
 "type": "splunk.singlevalue"
 },
 "viz_kpi_travelers": {
 "dataSources": {
 "primary": "ds_inter_campus"
 },
 "description": "Devices seen at multiple campuses",
 "options": {
 "majorColor": "#7B56DB"
 },
 "title": "Inter-campus travelers",
 "type": "splunk.singlevalue"
 },
 "viz_kpi_unique": {
 "dataSources": {
 "primary": "ds_kpi_unique_visitors"
 },
 "description": "Unique devices (by MAC) seen in the period.",
 "options": {
 "majorColor": "#049FD9"
 },
 "title": "Unique devices",
 "type": "splunk.singlevalue"
 },
 "viz_net_box": {
 "options": {
 "fillColor": "#FFFFFF",
 "strokeColor": "#E0E0E0"
 },
 "type": "splunk.rectangle"
 },
 "viz_net_hdr": {
 "options": {
 "fontColor": "#D64550",
 "markdown": "**Network Impact \u2014 Cross-Domain Intelligence**"
 },
 "type": "splunk.markdown"
 },
 "viz_net_intro": {
 "options": {
 "markdown": "Correlating **Cisco Spaces** occupancy & presence with **Cisco DNA Center** network health, client experience, and compliance data. These insights exist nowhere else \u2014 not in Spaces, not in DNAC."
 },
 "type": "splunk.markdown"
 },
 "viz_net_kpi_client_health": {
 "dataSources": {
 "primary": "ds_net_kpi_client_health"
 },
 "description": "DNAC overall client health (0-100).",
 "options": {
 "majorColor": "#049FD9",
 "numberPrecision": 0,
 "unit": "/100",
 "unitPosition": "after"
 },
 "title": "Client health",
 "type": "splunk.singlevalue"
 },
 "viz_net_kpi_compliance": {
 "dataSources": {
 "primary": "ds_net_kpi_compliance"
 },
 "description": "Network devices in COMPLIANT state (DNAC).",
 "options": {
 "majorColor": "#7B56DB",
 "numberPrecision": 1,
 "unit": "%",
 "unitPosition": "after"
 },
 "title": "Compliance rate",
 "type": "splunk.singlevalue"
 },
 "viz_net_kpi_health": {
 "dataSources": {
 "primary": "ds_net_kpi_health"
 },
 "description": "DNAC overall network health (0-100).",
 "options": {
 "majorColor": "#6EBE4A",
 "numberPrecision": 0,
 "unit": "/100",
 "unitPosition": "after"
 },
 "title": "Network health",
 "type": "splunk.singlevalue"
 },
 "viz_net_kpi_issues": {
 "dataSources": {
 "primary": "ds_net_kpi_issues"
 },
 "description": "Distinct DNAC issues active in the window.",
 "options": {
 "majorColor": "#D64550"
 },
 "title": "Active DNAC issues",
 "type": "splunk.singlevalue"
 },
 "viz_net_sub_hero": {
 "options": {
 "fontColor": "#000000",
 "markdown": "**The Convergence View** \u2014 occupancy alongside DNAC health, with issue markers"
 },
 "type": "splunk.markdown"
 },
 "viz_net_sub_infra": {
 "options": {
 "fontColor": "#000000",
 "markdown": "**Infrastructure Stress** \u2014 DNAC issues correlated with occupancy"
 },
 "type": "splunk.markdown"
 },
 "viz_net_sub_table": {
 "options": {
 "fontColor": "#000000",
 "markdown": "**Access Point Operations**"
 },
 "type": "splunk.markdown"
 },
 "viz_net_sub_xp": {
 "options": {
 "fontColor": "#000000",
 "markdown": "**Client Experience** \u2014 does occupancy degrade WiFi quality?"
 },
 "type": "splunk.markdown"
 },
 "viz_occupancy_vs_health": {
 "dataSources": {
 "primary": "ds_occupancy_vs_health"
 },
 "description": "Per-hour occupancy vs client-health scatter.",
 "options": {
 "backgroundColor": "transparent",
 "legendDisplay": "off",
 "seriesColors": [
 "#009ceb"
 ],
 "xAxisTitleText": "Occupancy (people detected)",
 "xField": "occupancy",
 "yAxisTitleText": "Client Health Score",
 "yField": "client_health"
 },
 "showLastUpdated": false,
 "showProgressBar": false,
 "title": "Spaces \u00d7 DNAC \u2014 occupancy vs. client-health correlation",
 "type": "splunk.scatter"
 },
 "viz_onboarding_vs_occupancy": {
 "dataSources": {
 "annotation": "ds_activation_annotation",
 "primary": "ds_onboarding_vs_occupancy"
 },
 "description": "Hourly occupancy with avg WiFi onboarding time overlay.",
 "options": {
 "annotationColor": [
 "#D64550"
 ],
 "annotationLabel": [
 "label"
 ],
 "backgroundColor": "transparent",
 "legendDisplay": "bottom",
 "overlayFields": [
 "Avg Onboarding (ms)"
 ],
 "seriesColors": [
 "#009ceb",
 "#ff677b"
 ],
 "xAxisTitleVisibility": "hide",
 "yAxisTitleText": "Occupancy"
 },
 "showLastUpdated": false,
 "showProgressBar": false,
 "title": "Spaces \u00d7 DNAC \u2014 occupancy (columns) + WiFi onboarding-time overlay",
 "type": "splunk.column"
 },
 "viz_p_hdr_bg": {
 "options": {
 "fillColor": "#ffffff",
 "strokeColor": "transparent"
 },
 "type": "splunk.rectangle"
 },
 "viz_p_hdr_title": {
 "options": {
 "fontColor": "#000000",
 "markdown": "### Cisco Spaces \u2014 Intelligence"
 },
 "type": "splunk.markdown"
 },
 "viz_room_box": {
 "options": {
 "fillColor": "#FFFFFF",
 "strokeColor": "#E0E0E0"
 },
 "type": "splunk.rectangle"
 },
 "viz_room_hdr": {
 "options": {
 "fontColor": "#D64550",
 "markdown": "**Room Utilization**"
 },
 "type": "splunk.markdown"
 },
 "viz_room_kpi_ghost": {
 "dataSources": {
 "primary": "ds_room_kpi_ghost"
 },
 "description": "Rooms never used in the period.",
 "options": {
 "majorColor": "#FF8C25"
 },
 "title": "Ghost rooms",
 "type": "splunk.singlevalue"
 },
 "viz_room_kpi_hot": {
 "dataSources": {
 "primary": "ds_room_kpi_hot"
 },
 "description": "Rooms with >50% avg utilization.",
 "options": {
 "majorColor": "#D64550"
 },
 "title": "Hot rooms",
 "type": "splunk.singlevalue"
 },
 "viz_room_kpi_total": {
 "dataSources": {
 "primary": "ds_room_kpi_total"
 },
 "description": "Rooms reporting data.",
 "options": {
 "majorColor": "#049FD9"
 },
 "title": "Total rooms",
 "type": "splunk.singlevalue"
 },
 "viz_room_pie": {
 "dataSources": {
 "primary": "ds_room_tier_pie"
 },
 "description": "Rooms grouped by utilization tier (Unused \u2192 Critical).",
 "options": {
 "seriesColors": [
 "#E0E0E0",
 "#6EBE4A",
 "#FF8C25",
 "#D64550"
 ]
 },
 "title": "Rooms by utilization tier",
 "type": "splunk.pie"
 },
 "viz_room_punchcard": {
 "dataSources": {
 "primary": "ds_room_punchcard"
 },
