 }
 },
 "ds_issues_with_occupancy": {
 "name": "Issues by severity and Occupancy overlay",
 "options": {
 "query": "index=* (sourcetype=\"cisco:dnac:issue\") OR (sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_COUNT\" deviceCounts.location.inferredLocationTypes{}=FLOOR)\n| eval metric=case(sourcetype=\"cisco:dnac:issue\", \"issue\",\n sourcetype=\"cisco:spaces:firehose\", \"occupancy\"),\n severity=if(metric=\"issue\", IssueSpecificSeverity, null()),\n users=if(metric=\"occupancy\", 'deviceCounts.userCount', null())\n| bin _time span=1h\n| stats dc(eval(if(metric=\"issue\" AND severity=\"HIGH\", IssueID, null()))) as High,\n dc(eval(if(metric=\"issue\" AND severity=\"MEDIUM\", IssueID, null()))) as Medium,\n dc(eval(if(metric=\"issue\" AND severity=\"LOW\", IssueID, null()))) as Low,\n max(users) as Occupancy by _time\n| eval Occupancy=round(Occupancy, 2)",
 "queryParameters": {
 "earliest": "$global_time.earliest$",
 "latest": "$global_time.latest$"
 }
 },
 "type": "ds.search"
 },
