 "options": {
 "query": "index=* (sourcetype=\"cisco:dnac:client\") OR (sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_COUNT\" deviceCounts.location.inferredLocationTypes{}=FLOOR)\n| eval metric=case(sourcetype=\"cisco:dnac:client\", \"onboard\",\n sourcetype=\"cisco:spaces:firehose\", \"occupancy\"),\n onboard_ms=if(metric=\"onboard\", 'onboarding.avgRunDuration', null()),\n users=if(metric=\"occupancy\", 'deviceCounts.userCount', null())\n| bin _time span=1h\n| stats max(users) as Occupancy, avg(onboard_ms) as onboard_avg by _time\n| where isnotnull(Occupancy)\n| eval Occupancy=round(Occupancy, 2),\n \"Avg Onboarding (ms)\"=round(onboard_avg, 2)\n| fields _time Occupancy \"Avg Onboarding (ms)\" ",
 "queryParameters": {
 "earliest": "$global_time.earliest$",
 "latest": "$global_time.latest$"
 }
 },
 "type": "ds.search"
 },
 "ds_room_kpi_ghost": {
 "type": "ds.chain",
 "name": "Ghost rooms",
 "options": {
 "extend": "ds_base_space_occupancy",
 "query": "| eval occupied=if(presence==\"OCCUPIED\" OR people>0, 1, 0)\n| stats sum(occupied) as occupied_count, count by room\n| eval ghost_pct=round((1 - occupied_count/count)*100, 2)\n| where ghost_pct >= 80\n| stats count as \"Ghost Rooms\""
 }
 },
 "ds_room_kpi_hot": {
