 }
 },
 "ds_room_punchcard": {
 "type": "ds.chain",
 "name": "Occupancy by day and hour",
 "options": {
 "extend": "ds_base_space_occupancy",
 "query": "| eval hour=strftime(_time, \"%H\"),\n dow=strftime(_time, \"%A\"),\n occupied=if(presence==\"OCCUPIED\", 1, 0)\n| stats sum(occupied) as occupancies by dow, hour\n| sort dow, hour"
 }
 },
 "ds_room_tier_pie": {
 "type": "ds.chain",
 "name": "Rooms by utilization tier",
 "options": {
 "extend": "ds_base_space_occupancy",
 "query": "| stats avg(people) as avg_people by room, capacity\n| eval util=if(capacity>0, avg_people/capacity, 0)\n| eval tier=case(util>=0.8, \"Hot (\u226580%)\", util>=0.4, \"Active (40-80%)\", util>0, \"Idle (<40%)\", 1=1, \"Empty\")\n| stats count by tier"
 }
 },
 "ds_room_top_bar": {
 "type": "ds.chain",
 "name": "Top 15 rooms by utilization",
 "options": {
 "extend": "ds_base_space_occupancy",
 "query": "| stats avg(people) as avg_people, max(people) as peak by room, capacity\n| eval util=if(capacity>0, round(avg_people/capacity*100, 2), 0)\n| sort - util\n| head 15\n| eval avg_people=round(avg_people, 1)\n| table room, avg_people, peak, util\n| rename room as \"Room\", avg_people as \"Avg People\", peak as \"Peak\", util as \"Util %\""
 }
 },
 "ds_room_util": {
 "type": "ds.chain",
 "name": "Room utilization detail",
 "options": {
 "extend": "ds_base_space_occupancy",
 "query": "| eval occupied=if(presence=\"true\", 1, 0),\n pct=if(capacity>0, round(people/capacity*100, 2), 0)\n| stats avg(pct) as \"Avg Util %\",\n max(pct) as \"Peak Util %\",\n avg(occupied) as occ_rate,\n latest(capacity) as Capacity,\n count as Reports by building, floor, room\n| eval \"Time Occupied %\"=round(occ_rate*100, 2),\n \"Avg Util %\"=round('Avg Util %', 2),\n \"Peak Util %\"=round('Peak Util %', 2)\n| fields building, floor, room, Capacity, \"Avg Util %\", \"Peak Util %\", \"Time Occupied %\", Reports\n| rename building as Building, floor as Floor, room as Room\n| sort Building, Floor, Room"
 }
 },
 "ds_sankey_flow": {
 "name": "Inter-campus device flow",
 "options": {
 "query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_PRESENCE\"\n| eval mac='devicePresence.macAddress'\n| eval bldg_self=if(mvfind('devicePresence.location.inferredLocationTypes{}', \"BUILDING\")>=0, 'devicePresence.location.name', null())\n| eval bldg_parent=if(mvfind('devicePresence.location.parent.inferredLocationTypes{}', \"BUILDING\")>=0, 'devicePresence.location.parent.name', null())\n| eval bldg_grand=if(mvfind('devicePresence.location.parent.parent.inferredLocationTypes{}', \"BUILDING\")>=0, 'devicePresence.location.parent.parent.name', null())\n| eval building=coalesce(bldg_self, bldg_parent, bldg_grand)\n| where isnotnull(mac) AND mac!=\"\" AND isnotnull(building) AND building!=\"\"\n| sort mac, _time\n| streamstats current=f last(building) as prev_building by mac\n| where isnotnull(prev_building) AND building!=prev_building\n| stats count by prev_building, building\n| rename prev_building as source, building as target, count as value\n| sort - value\n| head 20",
 "queryParameters": {
 "earliest": "$global_time.earliest$",
 "latest": "$global_time.latest$"
 }
 },
 "type": "ds.search"
 },
 "ds_ssid_composition": {
 "type": "ds.chain",
 "name": "Guest vs employee",
 "options": {
 "extend": "ds_base_device_association",
 "query": "| eval category=case(match(ssid, \"(?i)guest\"), \"Guest\", 1=1, \"Employee\")\n| stats count by category"
 }
 },
 "ds_ssid_daily": {
 "type": "ds.chain",
 "name": "Guest vs employee by day",
 "options": {
 "extend": "ds_base_device_association",
 "query": "| eval category=case(match(ssid, \"(?i)guest\"), \"Guest\", 1=1, \"Employee\")\n| timechart span=1d count by category"
 }
 },
 "ds_temp_trend": {
 "type": "ds.chain",
 "name": "Webex sensors \u2014 temperature by floor + exercise annotations",
 "options": {
 "extend": "ds_base_webex_telemetry",
 "query": "| where isnotnull(temp) AND isnotnull(device)\n| eval temp_f=round(temp*9/5+32, 2)\n| timechart span=1h avg(temp_f) as \"Temp \u00b0F\" by device limit=10"
 }
 },
 "ds_user_count_city": {
 "type": "ds.chain",
 "name": "Users by city over time",
 "options": {
 "extend": "ds_base_device_count",
 "query": "| where isnotnull(users) AND isnotnull(city)\n| bin _time span=1h\n| stats max(users) as peak by _time, city\n| stats max(peak) as \"Peak Users\" by city\n| sort - \"Peak Users\""
 }
 },
 "ds_visitor_daily": {
 "type": "ds.chain",
 "name": "Daily visitors with 7-day forecast",
 "options": {
 "extend": "ds_base_device_association",
 "query": "| bin _time span=1d\n| stats dc(mac) as \"Unique Devices\" by _time\n| predict \"Unique Devices\" future_timespan=7"
 }
 },
 "ds_visitor_map": {
 "type": "ds.search",
 "name": "Visitor volume by campus",
 "options": {
 "query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_COUNT\" deviceCounts.location.inferredLocationTypes{}=BUILDING\n| eval building='deviceCounts.location.name',\n devices='deviceCounts.deviceCount',\n users='deviceCounts.userCount'\n| stats latest(devices) as devices, latest(users) as visitors by building\n| eval lat=case(building=\"SEOC\", 30.4551,\n building=\"AUB\", 28.0653,\n match(building, \"(?i)tallahassee\"), 30.4383,\n match(building, \"(?i)auburndale\"), 28.0653,\n 1=1, 29.0),\n lon=case(building=\"SEOC\", -84.2530,\n building=\"AUB\", -81.7887,\n match(building, \"(?i)tallahassee\"), -84.2807,\n match(building, \"(?i)auburndale\"), -81.7887,\n 1=1, -82.0)\n| where isnotnull(lat)\n| eval devices=round(devices, 2), visitors=round(visitors, 2)\n| rename building as city\n| table city devices visitors lat lon",
 "queryParameters": {
 "earliest": "$global_time.earliest$",
 "latest": "$global_time.latest$"
 }
 }
 },
 "ds_week_compare": {
 "type": "ds.chain",
 "name": "This week vs last week",
 "options": {
 "extend": "ds_base_device_count",
 "query": "| bin _time span=1h\n| stats max(users) as peak by _time, floor\n| eval week=if(_time>=relative_time(now(), \"-7d\"), \"This Week\", \"Last Week\")\n| stats avg(peak) as \"Avg Peak Users\" by week\n| eval \"Avg Peak Users\"=round('Avg Peak Users', 0)"
 }
 },
 "ds_wifi_quality": {
 "name": "WiFi RSSI by SSID over time",
 "options": {
 "query": "index=* sourcetype=\"cisco:dnac:client\" connectionStatus=\"connected\"\n| eval rssi='connection.rssi',\n ssid='connection.ssid',\n band='connection.band',\n snr='connection.snr'\n| where isnotnull(rssi) AND rssi<0\n| bin _time span=1h\n| stats avg(rssi) as avg_rssi, avg(snr) as avg_snr by _time, ssid\n| timechart useother=t span=1h avg(eval(round(avg_rssi, 2))) as \"Avg RSSI (dBm)\" by ssid where max in top10",
 "queryParameters": {
 "earliest": "$global_time.earliest$",
 "latest": "$global_time.latest$"
 }
 },
 "type": "ds.search"
 },
 "ds_wifi_with_occupancy": {
 "name": "WiFi RSSI and Occupancy overlay",
 "options": {
 "query": "index=* (sourcetype=\"cisco:dnac:client\" connectionStatus=\"connected\") OR (sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_COUNT\" deviceCounts.location.inferredLocationTypes{}=FLOOR)\n| eval metric=case(sourcetype=\"cisco:dnac:client\", \"wifi\",\n sourcetype=\"cisco:spaces:firehose\", \"occupancy\"),\n rssi=if(metric=\"wifi\", 'connection.rssi', null()),\n users=if(metric=\"occupancy\", 'deviceCounts.userCount', null())\n| where (metric=\"wifi\" AND isnotnull(rssi) AND rssi<0) OR metric=\"occupancy\"\n| bin _time span=1h\n| stats avg(rssi) as rssi_avg, max(users) as Occupancy by _time\n| eval \"Avg RSSI (dBm)\"=round(rssi_avg, 2),\n Occupancy=round(Occupancy, 2)\n| fields _time \"Avg RSSI (dBm)\" Occupancy",
 "queryParameters": {
 "earliest": "$global_time.earliest$",
 "latest": "$global_time.latest$"
 }
 },
 "type": "ds.search"
 },
 "ds_base_device_count": {
 "type": "ds.search",
 "name": "[Base] Spaces firehose \u2014 DEVICE_COUNT (floor scope)",
 "options": {
 "query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_COUNT\" deviceCounts.location.inferredLocationTypes{}=FLOOR\n| eval users='deviceCounts.userCount',\n associated='deviceCounts.associatedCount',\n devices='deviceCounts.deviceCount',\n pct='deviceCounts.estimatedCapacityPercentage',\n floor='deviceCounts.location.name',\n building='deviceCounts.location.parent.name',\n city='deviceCounts.location.parent.parent.name'",
 "queryParameters": {
 "earliest": "$global_time.earliest$",
 "latest": "$global_time.latest$"
 }
 }
 },
 "ds_base_webex_telemetry": {
 "type": "ds.search",
 "name": "[Base] Spaces firehose \u2014 WEBEX_TELEMETRY",
 "options": {
 "query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"WEBEX_TELEMETRY\"\n| eval temp='webexTelemetryUpdate.telemetries{}.ambientTemp',\n humidity='webexTelemetryUpdate.telemetries{}.relativeHumidity',\n device='webexTelemetryUpdate.deviceInfo.serialNumber'",
 "queryParameters": {
 "earliest": "$global_time.earliest$",
 "latest": "$global_time.latest$"
 }
 }
 },
 "ds_base_device_association": {
 "type": "ds.search",
 "name": "[Base] Spaces firehose \u2014 DEVICE_ASSOCIATION (associates)",
 "options": {
 "query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_ASSOCIATION\" deviceAssociation.event=\"ASSOCIATE\"\n| eval mac='deviceAssociation.device.macAddress',\n ssid='deviceAssociation.ssid'",
 "queryParameters": {
 "earliest": "$global_time.earliest$",
 "latest": "$global_time.latest$"
 }
 }
 },
 "ds_base_space_occupancy": {
 "type": "ds.search",
 "name": "[Base] Spaces firehose \u2014 SPACE_OCCUPANCY",
 "options": {
 "query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"SPACE_OCCUPANCY\"\n| rename spaceOccupancy.space.name as room,\n spaceOccupancy.space.capacity as capacity,\n spaceOccupancy.peakPeopleCount as people,\n spaceOccupancy.peoplePresence as presence,\n spaceOccupancy.location.name as floor,\n spaceOccupancy.location.parent.name as building",
 "queryParameters": {
 "earliest": "$global_time.earliest$",
 "latest": "$global_time.latest$"
 }
 }
 },
 "ds_base_dnac_issue": {
 "type": "ds.search",
 "name": "[Base] DNAC \u2014 issue",
 "options": {
 "query": "`index_catalyst` sourcetype=\"cisco:dnac:issue\"",
 "queryParameters": {
 "earliest": "$global_time.earliest$",
 "latest": "$global_time.latest$"
 }
 }
 }
 },
